// Woojin CMS - SELECT fijo y acotado. NO aceptar SQL desde otros mensajes.
// El usuario SQL DEBE migrarse a una cuenta exclusiva SELECT.
const ultimo = flow.get('woojin_consulta_en_curso');
const ahora = Date.now();
if (ultimo && (ahora - ultimo < 20000)) {
    node.status({fill:'yellow',shape:'ring',text:'Consulta anterior en curso; omitida'});
    return null;
}
flow.set('woojin_consulta_en_curso', ahora);
msg.woojin_inicio_ms = ahora;
msg.topic = `SELECT
    Machine_IP, Machine_Name, Time_Stamp,
    Motor_Status, Heater_Status, Operation_Status,
    Cycle_Time_Before, Cycle_Time_Current,
    Production_Time_Hour, Production_Time_Min,
    Total_Quantity, Current_Quantity, Avg_Quantity_Per_Hour,
    Alarm_Status,
    TIMESTAMPDIFF(SECOND, Time_Stamp, NOW()) AS cms_age_seconds
FROM disal_cms.real_data
WHERE Machine_IP IN (
    '172.16.0.141', '172.16.0.143', '172.16.0.144',
    '172.16.0.145', '172.16.0.146'
)
LIMIT 5`;
// No parámetros arbitrarios: los cinco identificadores están fijados en el SQL.
msg.payload = [];
node.status({fill:'blue',shape:'dot',text:'Lectura SQL en curso'});
return msg;

// Procesamiento de SOLO LECTURA. Tres salidas:
// 1) resumen de 5 inyectoras; 2) eventos de incremento/reinicio;
// 3) puntos [fields,tags] PREPARADOS, SIN escribir a InfluxDB.
flow.set('woojin_consulta_en_curso', null);
const modelos = {
  '172.16.0.141':'DL650G5',
  '172.16.0.143':'TB280G5-1',
  '172.16.0.144':'TB280G5-2',
  '172.16.0.145':'TB200G5',
  '172.16.0.146':'DL450G5'
};
const ips = Object.keys(modelos);
const ahoraMs = Date.now();
const fechaLectura = new Date(ahoraMs).toISOString();
const duracionMs = typeof msg.woojin_inicio_ms === 'number' ? ahoraMs - msg.woojin_inicio_ms : null;
const SEC_EDAD_MAX = 10; // Umbral propuesto, NO especificación confirmada de Woojin.
const anterior = context.get('woojin_historial') || {};
const nuevos = {};
const eventos = [];
const puntos = [];
const vistos = {};
if (!Array.isArray(msg.payload)) {
    node.status({fill:'red',shape:'ring',text:'Respuesta SQL inesperada'});
    node.error('Woojin: msg.payload no es un arreglo SQL', msg);
    return null;
}
function numero(v) {
    if (v === null || v === undefined || v === '') return null;
    const n = Number(typeof v === 'string' ? v.replace(',', '.') : v);
    return Number.isFinite(n) ? n : null;
}
function fecha(v) {
    if (v === null || v === undefined) return null;
    if (v instanceof Date) return Number.isFinite(v.getTime()) ? v.toISOString() : null;
    return String(v); // Evitar reinterpretar zona horaria de DATETIME MariaDB.
}
function nombreEstado(x, positivos, negativos) {
    if (x === 1) return positivos;
    if (x === 0) return negativos;
    return 'NO_VALIDADO';
}
const salida = [];
for (const fila of msg.payload) {
    if (!fila || !Object.prototype.hasOwnProperty.call(modelos, String(fila.Machine_IP))) continue;
    const ip = String(fila.Machine_IP);
    if (vistos[ip]) continue;
    vistos[ip] = true;
    const edad = numero(fila.cms_age_seconds); // Calculada DENTRO de MariaDB: misma zona horaria que NOW().
    const fresca = edad !== null && edad >= -3 && edad <= SEC_EDAD_MAX;
    const anteriorMaquina = anterior[ip] || {};
    const cantidad = numero(fila.Current_Quantity);
    const cantidadAnterior = anteriorMaquina.contador;
    let delta = null;
    let eventoContador = 'SIN_REFERENCIA';
    let ultimoIncrementoMs = anteriorMaquina.ultimo_incremento_ms || null;
    if (!fresca) {
        eventoContador = 'SIN_EVALUAR_POR_FRESCURA';
    } else if (cantidad === null) {
        eventoContador = 'CONTADOR_INVALIDO';
    } else if (typeof cantidadAnterior !== 'number') {
        eventoContador = 'LINEA_BASE_INICIAL';
    } else {
        delta = cantidad - cantidadAnterior;
        if (delta > 0) {
            eventoContador = 'INCREMENTO_DETECTADO';
            ultimoIncrementoMs = ahoraMs;
            eventos.push({payload:{evento:'INCREMENTO_CONTADOR',machine_ip:ip,modelo:modelos[ip],incremento_observado:delta,contador_actual:cantidad,contador_anterior:cantidadAnterior,observado_en:fechaLectura,nota:'Los incrementos no equivalen necesariamente a piezas buenas ni a disparos individuales.'}});
        } else if (delta < 0) {
            eventoContador = 'REINICIO_O_RETROCESO_CONTADOR';
            ultimoIncrementoMs = null;
            eventos.push({payload:{evento:'REINICIO_O_RETROCESO_CONTADOR',machine_ip:ip,modelo:modelos[ip],contador_actual:cantidad,contador_anterior:cantidadAnterior,observado_en:fechaLectura}});
        } else {
            eventoContador = 'SIN_INCREMENTO_EN_ESTA_LECTURA';
        }
    }
    const ciclo = numero(fila.Cycle_Time_Current);
    const umbralActividadS = Math.max(90, ciclo !== null && ciclo > 0 ? ciclo * 3 : 0);
    let actividad = 'NO_DETERMINADA';
    if (!fresca) actividad = 'DATOS_CMS_DESACTUALIZADOS';
    else if (eventoContador === 'INCREMENTO_DETECTADO') actividad = 'INCREMENTO_RECIENTE';
    else if (ultimoIncrementoMs && (ahoraMs - ultimoIncrementoMs) <= umbralActividadS * 1000) actividad = 'ACTIVIDAD_DE_CONTADOR_RECIENTE';
    else if (eventoContador === 'REINICIO_O_RETROCESO_CONTADOR') actividad = 'CONTADOR_REINICIADO';
    else actividad = 'SIN_ACTIVIDAD_DE_CONTADOR_CONFIRMADA';
    const op = numero(fila.Operation_Status);
    const motor = numero(fila.Motor_Status);
    const heater = numero(fila.Heater_Status);
    const alarma = numero(fila.Alarm_Status);
    const elemento = {
        machine_ip: ip, modelo: modelos[ip], machine_name_cms: fila.Machine_Name,
        cms_timestamp: fecha(fila.Time_Stamp), cms_age_seconds: edad, cms_row_fresh: fresca,
        adquisicion_industrial_fresca: 'NO_VERIFICADA',
        operation_status_code: op,
        operation_status_text: op === 1 ? 'AUTO' : 'NO_VALIDADO',
        motor_status_code: motor, motor_status_text: nombreEstado(motor, 'RUN', 'STOP'),
        heater_status_code: heater, heater_status_text: nombreEstado(heater, 'RUN', 'STOP'),
        alarm_status_code: alarma, // Significado de 0/1 aún sin confirmar.
        cycle_time_current: ciclo,
        cycle_time_before: numero(fila.Cycle_Time_Before),
        production_time_hour: numero(fila.Production_Time_Hour),
        production_time_min: numero(fila.Production_Time_Min),
        current_quantity: cantidad,
        total_quantity: numero(fila.Total_Quantity),
        avg_quantity_per_hour: numero(fila.Avg_Quantity_Per_Hour),
        delta_contador_observado: delta,
        tipo_cambio_contador: eventoContador,
        actividad_inferida: actividad,
        ultimo_incremento_detectado: ultimoIncrementoMs ? new Date(ultimoIncrementoMs).toISOString() : null
    };
    salida.push(elemento);
    // Guardar SOLO muestras frescas y con contador válido como base comparativa.
    nuevos[ip] = {
        contador: fresca && cantidad !== null ? cantidad : cantidadAnterior,
        ultimo_incremento_ms: ultimoIncrementoMs
    };
    if (fresca) {
        const fields = {
            current_quantity: cantidad,
            total_quantity: numero(fila.Total_Quantity),
            cycle_time_current: ciclo,
            cycle_time_before: numero(fila.Cycle_Time_Before),
            avg_quantity_per_hour: numero(fila.Avg_Quantity_Per_Hour),
            operation_status_code: op,
            motor_status_code: motor,
            heater_status_code: heater,
            alarm_status_code: alarma,
            cms_age_seconds: edad,
            delta_contador_observado: delta
        };
        // InfluxDB rechaza campos null; no inventar ceros para valores ausentes.
        for (const k of Object.keys(fields)) if (fields[k] === null) delete fields[k];
        puntos.push({topic:'woojin_real_data',payload:[fields,{machine_ip:ip,modelo:modelos[ip]}],measurement:'woojin_real_data'});
    }
}
for (const ip of ips) {
    if (!vistos[ip]) salida.push({machine_ip:ip,modelo:modelos[ip],actividad_inferida:'SIN_FILA_SQL',cms_row_fresh:false,adquisicion_industrial_fresca:'NO_VERIFICADA'});
}
context.set('woojin_historial', Object.assign({}, anterior, nuevos));
const validas = salida.filter(x=>x.cms_row_fresh).length;
node.status({fill:validas===5?'green':'yellow',shape:'dot',text:validas+'/5 filas CMS frescas'});
const resumen = {
    payload: {
        fecha_recepcion_nodered: fechaLectura,
        cantidad_filas_sql: msg.payload.length,
        cantidad_maquinas_frescas_cms: validas,
        duracion_consulta_ms: duracionMs,
        aviso:'Frescura SQL no demuestra frescura Modbus. AUTO no demuestra producción.',
        maquinas: salida
    },
    topic:'woojin_resumen'
};
return [resumen, eventos.length ? eventos : null, puntos.length ? puntos : null];

if (Number(flow.get('envases_http_busy_until') || 0) > Date.now()) {
    return [null, { payload: { status: 'SKIPPED_BUSY', message: 'Solicitud anterior pendiente' } }];
}

const base = env.get('DISAL_API_BASE_URL');
const key = env.get('DISAL_ENVASES_INTEGRATION_KEY');

if (!base || !key) {
    return [null, { payload: { status: 'CONFIG_ERROR', message: 'Falta DISAL_API_BASE_URL o DISAL_ENVASES_INTEGRATION_KEY' } }];
}

if (!msg.payload || !Array.isArray(msg.payload.maquinas)) {
    return [null, { payload: { status: 'INVALID_SUMMARY', message: 'msg.payload.maquinas no es un arreglo' } }];
}

// El normalizador agrega marcadores SIN_FILA_SQL sin cms_timestamp.
// La API acepta lotes parciales, pero cada lectura enviada debe tener timestamp ISO válido.
const maquinas = msg.payload.maquinas.filter((maquina) =>
    maquina &&
    typeof maquina.machine_ip === 'string' &&
    typeof maquina.cms_timestamp === 'string' &&
    Number.isFinite(Date.parse(maquina.cms_timestamp))
);

if (maquinas.length === 0) {
    return [null, { payload: { status: 'NO_VALID_READINGS', received: msg.payload.maquinas.length, sent: 0 } }];
}

flow.set('envases_http_busy_until', Date.now() + 25000);

msg.method = 'POST';
msg.url = base.replace(/\/$/, '') + '/plants/ENVASES/telemetry/injection-machines';
msg.headers = {
    'content-type': 'application/json',
    'x-node-red-key': key
};
msg.payload = {
    ...msg.payload,
    source: 'NODE_RED_ENVASES',
    schemaVersion: 1,
    maquinas
};
msg.envasesBody = msg.payload;
msg.envasesAttempt = 0;
msg.envasesMachineCount = maquinas.length;
return [msg, null];

const statusCode = Number(msg.statusCode || 0);
const attempt = Number(msg.envasesAttempt || 0);
const shouldRetry = statusCode === 0 || statusCode === 429 || statusCode >= 500;

if (shouldRetry && attempt < 2) {
    msg.envasesAttempt = attempt + 1;
    msg.payload = msg.envasesBody;
    msg.headers = {
        'content-type': 'application/json',
        'x-node-red-key': env.get('DISAL_ENVASES_INTEGRATION_KEY')
    };
    return [msg, null];
}

flow.set('envases_http_busy_until', 0);
return [null, {
    payload: {
        statusCode,
        attempts: attempt + 1,
        sent: msg.envasesMachineCount,
        accepted: msg.payload && msg.payload.accepted,
        rejected: msg.payload && msg.payload.rejected,
        ignored: msg.payload && msg.payload.ignored,
        error: statusCode >= 400 ? (msg.payload && msg.payload.message) || 'Respuesta HTTP no exitosa' : undefined
    }
}];

const attempt = Number(msg.envasesAttempt || 0);
if (attempt < 2) {
    msg.envasesAttempt = attempt + 1;
    msg.payload = msg.envasesBody;
    msg.headers = {
        'content-type': 'application/json',
        'x-node-red-key': env.get('DISAL_ENVASES_INTEGRATION_KEY')
    };
    return [msg, null];
}

flow.set('envases_http_busy_until', 0);
return [null, {
    payload: {
        status: 'HTTP_ERROR',
        attempts: attempt + 1,
        sent: msg.envasesMachineCount,
        message: String((msg.error && msg.error.message) || 'Error de red').slice(0, 180)
    }
}];
